import"./chunk-2NFLSA4Y.js";var a={freeFall:{theory:{concept:"[[Free fall is the motion of a body under the action of gravity alone.]] Near the Earth\u2019s surface all bodies in free fall, heavy or light, have the same acceleration g \u2248 9.8 m/s\xB2, directed vertically downwards, so their velocity changes by 9.8 m/s downwards every second. In real air, drag makes light and wide bodies fall more slowly."},section:{freeFall:{title:"Free fall",text:"Drop a stone and its speed grows by about 9.8 m/s every second: 0, 9.8, 19.6, 29.4 m/s\u2026 This change per second is the free-fall acceleration g. Because the speed grows, the stone covers more and more distance each second \u2014 the dots of the strobe photo get farther apart. From 20 m it lands in about 2 s at about 20 m/s."},galileo:{title:"Heavy and light fall together",text:"For two thousand years people believed heavy bodies fall faster. [[Galileo showed that without air all bodies fall in the same way: a heavy body is pulled harder, but it is also harder to speed up.]] In 1971 the astronaut David Scott dropped a hammer and a feather on the airless Moon \u2014 they landed at the same moment."},throwUp:{title:"Throwing up",text:"A ball thrown upwards slows down by g every second until it stops for an instant at the top, after v\u2080 / g seconds, at the height v\u2080\xB2 / (2g). Then it falls back. Without air the way down mirrors the way up: it takes as long and lands with the same speed it was thrown with. [[At the top the speed is zero, but the acceleration is still g.]]"},throwDown:{title:"Throwing down",text:"A body thrown downwards starts with a speed and still gains g every second, so it lands sooner and faster than a dropped one. Its landing speed is \u221A(v\u2080\xB2 + 2gh\u2080) \u2014 the same as if it had been thrown up with v\u2080, because on the way back down it passes the start with that speed."},air:{title:"Air resistance",text:"In air, the faster a body falls the harder the air pushes back. At some speed the push equals the weight and the body stops speeding up: this is its terminal speed. A stone reaches about 40 m/s, a ping-pong ball about 9 m/s, a feather barely 1\u20132 m/s. That is why a feather falls slowly \u2014 not because it is light, but because the air holds it back."},example:{title:"In real life",text:"Skydivers fall at about 55 m/s (200 km/h) with their arms spread; the parachute lowers their terminal speed to about 5 m/s for a safe landing. Raindrops reach only a few m/s, so they do not hurt. A dropped smartphone hits the floor from 1.5 m at about 5.4 m/s."},check:{title:"Check your understanding",text:"How fast is a dropped stone after 3 s? (About 29 m/s.) How high does a ball thrown up at 10 m/s go? (About 5 m.) At the top of a throw, is the acceleration zero? (No, it is still g.) Do a hammer and a feather fall together on the Moon? (Yes.) Try each answer in the simulation."}},formula:{velocity:"Velocity after time t (up positive)",drop:"Distance fallen from rest",position:"Height at time t",maxHeight:"How high a ball thrown up rises",landing:"Speed after falling a height h with initial speed v\u2080",drag:"Acceleration with air resistance (v_t: terminal speed)"},variable:{terminal:"Terminal speed: the fastest a body falls in air"},assumption:{constantG:"g is the same at every height in the picture: the Earth is far bigger than 100 m.",air:"Without air resistance unless you turn it on; with it, a simple drag that grows with the square of the speed. A real feather also flutters and drifts sideways.",ground:"The body stops when it reaches the ground; it does not bounce.",scale:"The body and child are drawn larger than scale when needed to stay visible. The child stands at a rocky ledge with the body exactly at the starting height. At very low starting heights, the ground beneath the child is shown as a hollow."},param:{height:"Starting height",velocity:"Starting velocity (up +)",gravity:"Gravity",compare:"Drop a feather alongside",airResistance:"Air resistance",body:"Body",timeStep:"Simulation timestep"},hint:{height:"How high above the ground the body starts.",velocity:"0 \u2014 dropped. Positive \u2014 thrown up. Negative \u2014 thrown down.",compare:"A feather is released at the same moment. Do they land together?",airResistance:"With air, light and large bodies fall more slowly."},preset:{ground:"Ground",house:"House",pisa:"Tower of Pisa",drop:"Drop",up:"Throw up",down:"Throw down",stone:"Stone",tennis:"Tennis ball",pingPong:"Ping-pong ball"},measure:{height:"Height",velocity:"Velocity (up +)",landTime:"Time to land",landSpeed:"Landing speed",maxHeight:"Highest point",featherLandTime:"Feather lands after",topTime:"Time to the top",predictedLandTime:"Landing time from the formula (no air)",predictedLandSpeed:"Landing speed from the formula (no air)",terminalFraction:"Share of terminal speed reached"},view:{feather:"feather",strobe:"Dots: position every {interval}",top:"Top: {height} after {time}",landed:"Landed after {time} at {speed}",both:"Body: {body} \xB7 feather: {feather}",strobeOption:"Strobe dots and top",accelerationOption:"Accelerations"},graph:{height:"Height against time",velocity:"Velocity against time"},challenge:{twoSeconds:{title:"Two seconds",description:"Drop a body (without air) so that it lands after exactly 2 s.",hint:"h = g \xB7 t\xB2 / 2: about 19.6 m."},highThrow:{title:"Twenty metres up",description:"Throw a ball up from the ground so that it rises at least 20 m.",hint:"h_max = v\u2080\xB2 / (2g): you need about 20 m/s."},galileo:{title:"Galileo was right",description:"Drop a body and a feather together so that they land at the same moment.",hint:"Turn off air resistance."},feather:{title:"The feather lags behind",description:"Make the feather land at least 3 s after the body.",hint:"Turn on air resistance and drop from a good height."},moon:{title:"Throwing on the Moon",description:"On the Moon (g = 1.62 m/s\xB2), throw a ball up from the ground to at least 20 m.",hint:"Weaker gravity needs a much smaller starting speed than on the Earth."},terminal:{title:"Terminal speed",description:"With air resistance, let a body reach at least 95 % of its terminal speed before it lands.",hint:"A ping-pong ball reaches its terminal speed quickly; a stone needs a great height."}}}},o={sim:a};export{o as default,a as sim};
